def table(z):
    def cell(v):
        if pd.isna(v):return ''
        if isinstance(v,(float,np.floating)):return f'{v:.6f}'
        return str(v).replace('|','\\|').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(map(str,z.columns))+' |','| '+' | '.join(['---']*len(z.columns))+' |']+['| '+' | '.join(cell(v) for v in row)+' |' for row in z.itertuples(index=False,name=None)])
